      \marginparwidth=\textwidth
      \textwidth=\@tempskipa
    \fi
  \fi
  \ta@vblk=\paperheight
  \divide\ta@vblk by\ta@div
  \topmargin=-1in
  \advance\topmargin by\ta@vblk
  \if@hincl \else
    \advance\topmargin by-\headheight
    \advance\topmargin by-\headsep
  \fi
